const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
let language='fr';
const nav=$('.goo-nav'),blob=$('.nav-blob');
function moveBlob(link){if(!link)return;const n=nav.getBoundingClientRect(),r=link.getBoundingClientRect();blob.style.width=r.width+'px';blob.style.transform=`translateX(${r.left-n.left-5}px)`}
window.addEventListener('resize',()=>moveBlob($('.nav-link.active')));moveBlob($('.nav-link.active'));

const pageIds=['projects','level-design','systems'];
const album=$('#portfolioAlbum'),track=$('#albumTrack');
let currentPage=0;
function showPage(index, updateHash=true){
  currentPage=Math.max(0,Math.min(pageIds.length-1,index));
  const id=pageIds[currentPage];
  pageIds.forEach((pageId,i)=>{
    const sheet=document.getElementById(pageId);
    if(sheet) sheet.classList.toggle('is-active',i===currentPage);
  });
  $$('.folder-tab').forEach((tab,i)=>{
    const selected=i===currentPage;
    tab.classList.toggle('is-active',selected);
    tab.setAttribute('aria-selected',selected?'true':'false');
  });
  const active=$(`.nav-link[data-section="${id}"]`);
  $$('.nav-link').forEach(a=>a.classList.toggle('active',a===active));
  moveBlob(active);
  $('#albumPageNumber').textContent=String(currentPage+1).padStart(2,'0');
  $('#albumProgressFill').style.width=`${(currentPage+1)/3*100}%`;
  $('#albumPrev').disabled=currentPage===0;
  $('#albumNext').disabled=currentPage===2;
  if(updateHash) history.replaceState(null,'',`#${id}`);
  const page=document.getElementById(id);
  if(page) page.scrollTop=0;
}
function pageFromHash(){
  const id=location.hash.slice(1);
  const index=pageIds.indexOf(id);
  if(index>=0) showPage(index,false);
}
$$('.nav-link').forEach(link=>link.addEventListener('click',e=>{
  e.preventDefault(); showPage(pageIds.indexOf(link.dataset.section));
}));
$$('.folder-tab').forEach(tab=>tab.addEventListener('click',()=>showPage(Number(tab.dataset.page))));
$('#albumPrev').addEventListener('click',()=>showPage(currentPage-1));
$('#albumNext').addEventListener('click',()=>showPage(currentPage+1));
document.addEventListener('click',e=>{
  const anchor=e.target.closest('a[href="#projects"],a[href="#level-design"],a[href="#systems"]');
  if(anchor){e.preventDefault();showPage(pageIds.indexOf(anchor.getAttribute('href').slice(1)));}
});
window.addEventListener('hashchange',pageFromHash);
document.addEventListener('keydown',e=>{
  if(e.key==='ArrowRight' && !e.target.closest('input,textarea,dialog')) showPage(currentPage+1);
  if(e.key==='ArrowLeft' && !e.target.closest('input,textarea,dialog')) showPage(currentPage-1);
});
let touchStartX=0,touchStartY=0;
album.addEventListener('touchstart',e=>{touchStartX=e.changedTouches[0].clientX;touchStartY=e.changedTouches[0].clientY;},{passive:true});
album.addEventListener('touchend',e=>{
  const dx=e.changedTouches[0].clientX-touchStartX,dy=e.changedTouches[0].clientY-touchStartY;
  if(Math.abs(dx)>65 && Math.abs(dx)>Math.abs(dy)*1.25) showPage(currentPage+(dx<0?1:-1));
},{passive:true});
pageFromHash();
if(!pageIds.includes(location.hash.slice(1))) showPage(0,false);
const langToggle=$('#langToggle');
function setLanguage(lang){language=lang;document.documentElement.lang=lang;langToggle.innerHTML=lang==='fr'?'EN <i>↗</i>':'FR <i>↗</i>';$$('[data-fr][data-en]').forEach(el=>{const value=el.dataset[lang];if(value!==undefined){if(el.tagName==='H2'&&value.includes('<'))el.innerHTML=value;else el.textContent=value;}});if(activeSystem){renderSystemDetails(activeSystem);}}
langToggle.addEventListener('click',()=>setLanguage(language==='fr'?'en':'fr'));
$$('.filter').forEach(btn=>btn.addEventListener('click',()=>{$$('.filter').forEach(b=>b.classList.remove('active'));btn.classList.add('active');$$('.project-card').forEach(card=>{card.hidden=btn.dataset.filter!=='all'&&card.dataset.type!==btn.dataset.filter;});}));
const dialog=$('#systemDialog');let activeSystem=null;
const systemInfo={"thermal":{"title":"SIMULATION THERMIQUE","eyebrow":"SYS / 001 — STATES & PROPAGATION","fr":"Le système représente chaque objet par des variables dynamiques indépendantes (Heat, Humidity, Electricity) et un état courant IElementState. ElementSimulation initialise ses ElementInfo, remet les valeurs à leur état de départ et exécute à chaque frame les règles de transformation puis la logique de l’état. L’évaporation consomme de l’humidité et de la chaleur ; l’électricité décroît progressivement ; les valeurs sont bornées entre 0 et 100. LogicWeather ramène les paramètres vers les conditions de référence. Les états spécialisés (dont NormalState et BurningState dans les extraits transmis) pilotent les transitions, les effets visuels, les dégâts environnementaux et la propagation. PoolManager estime les besoins à partir des ElementSimulation de la scène, puis PrefabPool préchauffe et réutilise les instances. Les cinq scripts visibles sont les extraits fournis ; les interfaces, canaux, autres états et composants associés restent des dépendances.","en":"Each object is represented by independent dynamic values (Heat, Humidity, Electricity) and a current IElementState. ElementSimulation initializes its ElementInfo components, resets values and runs transformation rules before state logic every frame. Evaporation consumes humidity and heat; electricity decays over time; values are clamped between 0 and 100. LogicWeather moves parameters back toward reference conditions. Specialized states (including NormalState and BurningState in the supplied excerpts) handle transitions, visual effects, environmental damage and propagation. PoolManager estimates needs from ElementSimulation instances in the scene, then PrefabPool prewarms and reuses instances. The five visible scripts are the supplied excerpts; interfaces, channels, other states and related components remain dependencies.","architecture":"ElementSimulation\n ├─ ElementData / ElementInfo\n ├─ Heat · Humidity · Electricity\n ├─ IElementState (Normal / Hot / Frozen / Burning / Electricity)\n ├─ Absorbe<T> / Propagation<T>\n ├─ VFXManager / ProblemRegistry\n └─ PoolManager / PrefabPool / PooledInstance","flow":"Initialisation de l’élément → évolution des variables → évaluation de l’état → changement d’état / effets → propagation éventuelle → retour progressif vers les valeurs de référence.","points":["ElementSimulation : agrège les valeurs physiques, les ElementInfo, l’état courant et les appels d’absorption / propagation.","NormalState : surveille les seuils et bascule vers les états chaud, gelé ou électrifié.","BurningState : applique les dégâts environnementaux, déclenche la propagation de chaleur et quitte la combustion sous un seuil.","PoolManager : calcule les besoins de pré-instanciation à partir des éléments présents dans la scène.","PrefabPool : fournit, réinitialise et libère les GameObjects réutilisables via ObjectPool."],"scripts":[{"name":"ElementSimulation.cs","code":"using System.Collections.Generic;\nusing Goblfin;\nusing Project.Scripts.Core.ElementSysteme.RunTime.Data;\nusing Project.Scripts.Core.ElementSysteme.RunTime.Utilities;\nusing Runtime.Project.Scripts.Core;\nusing UnityEngine;\n\nnamespace Project.Scripts.Core.ElementSysteme.RunTime\n{\n\tpublic class ElementSimulation : MonoBehaviour\n\t{\n\t\t[Header(\"References\")]\n\t\t[field:SerializeField] public ElementData ElementData { get; private set; }\n\t\t[SerializeField] private List<ElementInfo> elementInfos =  new List<ElementInfo>();\n\t\t[field:SerializeField] public Collider Collider{ get; private set; }\n\t\t\n\t\t[Header(\"Dynamics Variables\")] \n\t\t[field:SerializeField] public float Heat{ get; set; }\n\t\t[field:SerializeField] public float Humidity{ get; set; }\n\t\t[field:SerializeField] public float Electricity{ get; set; }\n\t\t\n\t\tprivate float currentDegrees;\n\t\tpublic IElementState CurrentState { get; private set; }\n\t\t[Header(\"References\")]\n\t\t[SerializeField] private GameObject root;\n\t\t[field:SerializeField] public VFXManager  vfxManager;\n\t\tpublic GameObject Root\n\t\t{\n\t\t\tget\n\t\t\t{\n\t\t\t\tif (root != null) return root;\n\t\t\t\tvar pooled = GetComponentInParent<PooledInstance>();\n\t\t\t\treturn pooled != null ? pooled.gameObject : gameObject;\n\t\t\t}\n\t\t}\n\t\tprivate void Awake()\n\t\t{\n\t\t\tElementInfo[] found = GetComponents<ElementInfo>();\n\t\t\telementInfos.AddRange(found);\n\t\t\tforeach (var elementInfo in elementInfos)\n\t\t\t{\n\t\t\t\telementInfo.Init(this);\n\t\t\t}\n\t\t\tCollider = GetComponent<Collider>();\n\t\t}\n\n\t\tpublic T GetInfo<T>() where T : ElementInfo\n\t\t{\n\t\t\tforeach (var elementInfo in elementInfos)\n\t\t\t{\n\t\t\t\tif(elementInfo is T info)\n\t\t\t\t\treturn info;\n\t\t\t}\n\t\t\treturn null;\n\t\t}\n\n\t\tpublic void Start()\n\t\t{\n\t\t\tResetSimulation();\n\t\t}\n\n\t\tprivate void OnEnable() => ResetSimulation();\n\n\t\tprivate void ResetSimulation()\n\t\t{\n\t\t\tHeat = ElementData.AverageDegree;\n\t\t\tHumidity = 0;\n\t\t\tElectricity = 0f;\n\t\t\tChangeState(new NormalState());\n\t\t}\n\n\t\tprivate void Update()\n\t\t{\n\t\t\tLogicElement();\n\t\t\tCurrentState.Update(this);\n\t\t\tif(Heat <= 0.2f) return;\n\t\t\tLogicWeather();\n\t\t}\n\t\t\n\t\tpublic void ChangeState(IElementState state)\n\t\t{\n\t\t\tstate.Exit(this);\n\t\t\tCurrentState = state;\n\t\t\tstate.Enter(this);\n\t\t}\n\t\tprivate void LogicWeather()\n\t\t{\n\t\t\tHeat = Mathf.MoveTowards(Heat, ElementData.AverageDegree, Time.deltaTime / 2);\n\t\t\tHumidity = Mathf.MoveTowards(Humidity, 0, Time.deltaTime / 2);\n\t\t\tfloat targetDegrees = ElementData.AverageDegree + Heat - (Humidity * 0.1f);\n\t\t\tcurrentDegrees = Mathf.MoveTowards(currentDegrees, targetDegrees, 10f * Time.deltaTime);\n\t\t}\n\t\tprivate void LogicElement()\n\t\t{\n\t\t\tvar dt = Time.deltaTime;\n\t\t\tif (Humidity > 0f && Heat > 0f)\n\t\t\t{\n\t\t\t\tfloat evaporated = Mathf.Min(Humidity, Heat * ElementData.EvaporationSpeed * dt);\n\t\t\t\tHumidity -= evaporated;\n\t\t\t\tHeat -= evaporated * 2;\n\t\t\t}\n\t\t\tif (Heat < 0.1f) Heat = 0f;\n\t\t\tif (Electricity >= 0.1f)\n\t\t\t{\n\t\t\t\tElectricity -= 2 * dt;\n\t\t\t\tif (Electricity < 0.1f) Electricity = 0f;\n\t\t\t}\n\t\t\tif (Electricity < 0.1f) Electricity = 0f;\n\t\t\tHeat = Mathf.Clamp(Heat, 0f, 100f);\n\t\t\tHumidity = Mathf.Clamp(Humidity, 0f, 100f);\n\t\t\tElectricity = Mathf.Clamp(Electricity, 0f, 100f);\n\t\t}\n\t\tpublic void AddHeat(float heat) => Absorbe<HeatChannel>.Run(this, heat);\n\t\tpublic void AddHumidity(float humidity) => Absorbe<HumidityChannel>.Run(this, humidity);\n\t\tpublic void AddElectricity(float electricity) => Absorbe<ElectricityChannel>.Run(this, electricity);\n\t\tpublic void FirePropagation() => Propagation<HeatChannel>.Run(this);\n\t\tpublic void ElectricityPropagation() => Propagation<ElectricityChannel>.Run(this);\n\t}\n}"},{"name":"BurningState.cs","code":"using Project.Scripts.Core.ElementSysteme;\nusing Project.Scripts.Core.ElementSysteme.RunTime;\nusing Project.Scripts.Core.ElementSysteme.RunTime.ElementState;\nusing Runtime.Project.Scripts.Core;\nusing UnityEngine;\n\nnamespace Goblfin\n{\n\tpublic class BurningState: IElementState\n\t{\n\t\tprivate Health currentHealth;\n\t\tpublic void Enter(ElementSimulation element)\n\t\t{\n\t\t\tDebug.Log(\"Entering BurningState\");\n\t\t\telement.vfxManager.VfxState(VFXManager.States.fire);\n\t\t\tcurrentHealth = element.GetInfo<Health>();\n\t\t\tcurrentHealth.SetDeathVisual(DeathVisual.Burned);\n\t\t\tProblemRegistry.RegisterProblem(element, TypeOfProblem.Burn);\n\t\t}\n\t\tpublic void Update(ElementSimulation element)\n\t\t{\n\t\t\tcurrentHealth.TakeDamageEnv(element.ElementData.FireHitPower);\n\t\t\telement.FirePropagation();\n\t\t\tif (element.Heat <= element.ElementData.GoBurnState)\n\t\t\t\telement.ChangeState(new HotState());\n\t\t}\n\t\tpublic void Exit(ElementSimulation element)\n\t\t{\n\t\t}\n\t}\n}"},{"name":"NormalState.cs","code":"using Project.Scripts.Core.ElementSysteme;\nusing Project.Scripts.Core.ElementSysteme.RunTime;\nusing Project.Scripts.Core.ElementSysteme.RunTime.ElementState;\nusing Runtime.Project.Scripts.Core;\nusing UnityEngine;\nusing UnityEngine.Audio;\n\nnamespace Goblfin\n{\n    public class NormalState : IElementState\n    {\n\t    private Health currentHealth;\n        public void Enter(ElementSimulation element)\n        {\n            element.vfxManager.VfxState(VFXManager.States.normal);\n            ProblemRegistry.UnregisterProblem(element,TypeOfProblem.Burn);\n        }\n        public void Update(ElementSimulation element)\n        {\n            if (element.Heat > element.ElementData.GoHotState)\n                element.ChangeState(new HotState());\n            if (element.Humidity > element.ElementData.GoFrozenState)\n            {\n                if (!element.ElementData.IsLiquid)\n                    element.Collider.isTrigger = false;\n                element.ChangeState(new FrozenState());\n            }\n            if (element.Electricity > element.ElementData.GoElectrifyState)\n                element.ChangeState(new ElectricityState());\n        }\n        public void Exit(ElementSimulation element)\n        {\n        }\n    }\n}"},{"name":"PoolManager.cs","code":"using System.Collections.Generic;\nusing Goblfin;\nusing Project.Scripts.Core.ElementSysteme.RunTime.Data;\nusing UnityEngine;\n\nnamespace Project.Scripts.Core.ElementSysteme.RunTime.PoolObjectSysteme\n{\n    public class PoolManager : MonoBehaviour\n    {\n        [Header(\"Scan\")]\n        [SerializeField] private int maxPerPrefab = 64;\n\n        private void Start()\n        {\n            var needed = new Dictionary<GameObject, int>();\n            CountElementPrefabs(needed);\n            foreach (var (prefab, count) in needed)\n                PrefabPool.Prewarm(prefab, Mathf.Min(count, maxPerPrefab));\n        }\n\n        private static void CountElementPrefabs(Dictionary<GameObject, int> needed)\n        {\n            var sims = FindObjectsByType<ElementSimulation>(FindObjectsInactive.Include, FindObjectsSortMode.None);\n            var perData = new Dictionary<ElementData, int>();\n            foreach (ElementSimulation sim in sims)\n            {\n                if (sim.ElementData == null) continue;\n                perData[sim.ElementData] = perData.GetValueOrDefault(sim.ElementData) + 1;\n            }\n            foreach (var (data, simCount) in perData)\n            {\n                int count = Mathf.Clamp(simCount, 1, data.PoolSize);\n                foreach (GameObject prefab in data.GetPoolPrefabs())\n                    needed[prefab] = needed.GetValueOrDefault(prefab) + count;\n            }\n        }\n    }\n}"},{"name":"PrefabPool.cs","code":"using System.Collections.Generic;\nusing Runtime.Project.Scripts.Core;\nusing UnityEngine;\nusing UnityEngine.Pool;\n\nnamespace Goblfin\n{\n\tpublic static class PrefabPool\n\t{\n\t\tprivate static readonly Dictionary<GameObject, ObjectPool<GameObject>> Pools = new();\n\t\tprivate static readonly HashSet<GameObject> Prewarmed = new();\n\n\t\tpublic static void Prewarm(GameObject prefab, int count)\n\t\t{\n\t\t\tObjectPool<GameObject> pool = GetPool(prefab);\n\t\t\tvar temp = new List<GameObject>(count);\n\t\t\tfor (int i = 0; i < count; i++) temp.Add(pool.Get());\n\t\t\tforeach (GameObject go in temp) pool.Release(go);\n\t\t}\n\n\t\tpublic static GameObject Get(GameObject prefab, Vector3 position, Quaternion rotation)\n\t\t{\n\t\t\tObjectPool<GameObject> pool = GetPool(prefab);\n\t\t\tGameObject instance;\n\t\t\tdo { instance = pool.Get(); }\n\t\t\twhile (instance == null);\n\t\t\tinstance.transform.SetPositionAndRotation(position, rotation);\n\t\t\tinstance.SetActive(true);\n\t\t\treturn instance;\n\t\t}\n\n\t\tprivate static ObjectPool<GameObject> GetPool(GameObject prefab)\n\t\t{\n\t\t\tif (Pools.TryGetValue(prefab, out var pool)) return pool;\n\t\t\tpool = new ObjectPool<GameObject>(\n\t\t\t\tcreateFunc: () =>\n\t\t\t\t{\n\t\t\t\t\tGameObject go = Object.Instantiate(prefab);\n\t\t\t\t\tgo.AddComponent<PooledInstance>().source = prefab;\n\t\t\t\t\treturn go;\n\t\t\t\t},\n\t\t\t\tactionOnRelease: go => go.SetActive(false),\n\t\t\t\tactionOnDestroy: go => { if (go != null) Object.Destroy(go); },\n\t\t\t\tdefaultCapacity: 8,\n\t\t\t\tmaxSize: 64);\n\t\t\tPools[prefab] = pool;\n\t\t\treturn pool;\n\t\t}\n\n\t\tpublic static void Release(GameObject instance)\n\t\t{\n\t\t\tif (!instance.gameObject.activeSelf) return;\n\t\t\tif (instance.TryGetComponent(out PooledInstance pooled)\n\t\t\t    && Pools.TryGetValue(pooled.source, out ObjectPool<GameObject> pool))\n\t\t\t\tpool.Release(instance);\n\t\t\telse\n\t\t\t\tObject.Destroy(instance);\n\t\t}\n\n\t\t[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]\n\t\tprivate static void Reset() => Pools.Clear();\n\t}\n}"}],"videos":[["SIMULATION — DÉMO 01","assets/videos/thermal-simulation-01.mp4"],["SIMULATION — DÉMO 02","assets/videos/thermal-simulation-02.mp4"],["SIMULATION — DÉMO 03","assets/videos/thermal-simulation-03.mp4"]]},"controller":{"title":"CHARACTER CONTROLLER","eyebrow":"SYS / 002 — MODULAR MOVEMENT","fr":"Le contrôleur sépare l’orchestration du personnage et les responsabilités de déplacement. CharacterSetup initialise les composants IAptitude trouvés dans les enfants, récupère les services nécessaires, puis pilote les transitions IMoveState. À chaque frame, il met à jour le GroundChecker, vérifie la possibilité d’escalader, maintient une fenêtre de coyote time et délègue gravité, saut, déplacement et rotation à MovementBase. Les états Vault, Climb et LedgeClimb peuvent prendre la main sur la boucle de déplacement standard. Le franchissement est déclenché par la vitesse ou par l’entrée de saut : Vaulting détecte un obstacle par deux raycasts puis sélectionne une configuration VaultAnimData selon la hauteur et la vitesse. Les extraits ci-dessous montrent les quatre scripts transmis ; les autres états et composants référencés restent des dépendances du projet.","en":"The controller separates character orchestration from movement responsibilities. CharacterSetup initializes child components implementing IAptitude, retrieves required services, then drives IMoveState transitions. Each frame it updates GroundChecker, checks climbing, maintains a coyote-time window and delegates gravity, jumping, movement and rotation to MovementBase. Vault, Climb and LedgeClimb can take control of the standard movement loop. Vaulting is triggered by speed or jump input: two raycasts detect an obstacle, then VaultAnimData is selected from obstacle height and current speed. The code viewer contains the four scripts supplied; other referenced states and components remain project dependencies.","architecture":"CharacterSetup\n ├─ IAptitude / GetAptitude<T>()\n ├─ IMoveState / GoTo(state)\n ├─ MovementBase\n ├─ GroundChecker / RaycastChecker\n └─ Vaulting / VaultAnimData","flow":"Initialisation des aptitudes → NormalWalk → lecture des entrées et analyse du sol → mise à jour de l’état → déplacement / gravité → détection automatique du Vault.","points":["CharacterSetup : point d’entrée du contrôleur, initialisation des aptitudes et orchestration des états.","MovementBase : déplacement relatif à la caméra, accélération/décélération, gravité, saut, escalade et glissade.","Vaulting : détection de l’obstacle et sélection d’une animation compatible avec les paramètres de franchissement.","NormalWalk : état de locomotion de base qui arbitre interaction, glissade, escalade, combat, course et accroupissement."],"scripts":[{"name":"CharacterSetup.cs","code":"using System;\nusing System.Collections.Generic;\nusing CharacterController.SaverioScript.PlayerControllers.CharacterController;\nusing CharacterController.Script;\nusing CharacterController.Script.PlayerControllers;\nusing CharacterController.Script.PlayerControllers.Utilities;\nusing CharacterController.Utilities;\nusing UnityEngine;\n\nnamespace CharacterController\n{\n    public class CharacterSetup : MonoBehaviour\n    {\n        [Header(\"References\")]\n        [field: SerializeField] public Camera Cam { get; private set; }\n        [field: SerializeField] public CharacterData CharacterData { get; private set; }\n        [field: SerializeField] public ReadInput ReadInput { get; private set; }\n        [field: SerializeField] public MovementBase MovementBase { get; private set; }\n        [field: SerializeField] public Animator Animator { get; private set; }\n        [field: SerializeField] public CrateGrabber Grabber { get; private set; }\n        \n        [Header(\"Debug Booleans\")]\n        [field: SerializeField] public bool Grounded { get; private set; }\n        [field: SerializeField] public bool Climb { get; private set; }\n        public bool Sliding => GroundInfo.Touching && !GroundInfo.Walkable;\n        public bool CanJump => (Grounded || Sliding) && MovementBase.VerticalVelocity <= 0.1f;\n        \n        [Header(\"Settings\")]\n        [SerializeField] private float coyoteTime = 1f;\n        [SerializeField] private float enterFallstate;\n        [field: SerializeField] public float airSpeedCap = 8;\n        \n        public GroundInfo GroundInfo => groundChecker.Info;\n        private float coyoteTimeCounter;\n        private float currentFallstate = 0f;\n        public IMoveState MoveState { get; private set; }\n        public event Action<IMoveState> OnStateChanged;\n        public IReadOnlyList<IAptitude> Aptitudes => aptitudes;\n        private readonly List<IAptitude> aptitudes = new();\n        private GroundChecker groundChecker;\n        \n        private void Reset()\n        {\n            Animator = GetComponentInChildren<Animator>();\n            Cam = Camera.main;\n        }\n        private void Awake()\n        {\n            if (Cam == null) Cam = Camera.main;\n            GetComponentsInChildren(true, aptitudes);\n            foreach (var aptitude in aptitudes)\n                aptitude.Initialize(this);\n        }\n        private void Start()\n        {\n            groundChecker = GetAptitude<GroundChecker>();\n            Grabber =  GetAptitude<CrateGrabber>();\n            GoTo(new NormalWalk());\n        }\n        private void OnEnable()\n        {\n            ReadInput.OnAttackPressed += HandleAttackPressed;\n        }\n        private void OnDisable()\n        {\n            ReadInput.OnAttackPressed -= HandleAttackPressed;\n        }\n        private void Update()\n        {\n            var cc = MovementBase.Controller;\n            var origin = cc.transform.position + Vector3.up * 0.1f;\n            groundChecker.Check();\n            \n            Climb = RaycastChecker.Check(origin, cc.transform.forward, 0.8f, GameLayers.Climb, out _, new Color(1, 0, 0));\n\n            if(groundChecker.Info.Walkable)\n                coyoteTimeCounter = coyoteTime;\n            else\n                coyoteTimeCounter -= Time.deltaTime;\n            Grounded = coyoteTimeCounter >0;\n            \n            MoveState.UpdateState(this);\n    \n            if (MoveState is VaultState or ClimbState or LedgeClimbState) \n                return;\n\n            if (!Grounded)\n                MovementBase.ApplyGravity(this);\n            \n            MovementBase.Jump(this);\n            MovementBase.HandleMovement(this, Cam);\n            MovementBase.HandleRotation(CharacterData.rotationSpeed, Cam);\n            \n            if (Grounded || Sliding)\n                currentFallstate = 0f;\n            else if (MoveState is not FallState)\n            {\n                currentFallstate += Time.deltaTime;\n                if (currentFallstate > enterFallstate)\n                {\n                    GoTo(new FallState());\n                    currentFallstate = 0f;\n                }\n            }\n            \n            if (MovementBase.CurrentMoveDirection.magnitude > CharacterData.vaultAutoSpeedThreshold)\n                Vaulting.TryVault(this, MovementBase.CurrentMoveDirection.magnitude);\n        }\n        public T GetAptitude<T>() where T : class, IAptitude\n        {\n            foreach (var aptitude in aptitudes)\n                if (aptitude is T found)\n                    return found;\n            return null;\n        }\n        private void HandleAttackPressed()\n        {\n            if (MovementBase.Controller.isGrounded)\n                GoTo(new AttackState(CharacterData.firstAttack));\n        }\n        public void GoTo(IMoveState state)\n        {\n            MoveState?.ExitState(this);\n            MoveState = state;\n            MoveState?.EnterState(this);\n            OnStateChanged?.Invoke(state);\n        }\n    }\n}"},{"name":"MovementBase.cs","code":"using CharacterController.SaverioScript.PlayerControllers.CharacterController;\nusing CharacterController.Script.PlayerControllers;\nusing CharacterController.Script.PlayerControllers.Utilities;\nusing CharacterController.Utilities;\nusing UnityEngine;\n\nnamespace CharacterController.Script\n{\n\tpublic class MovementBase : MonoBehaviour,IAptitude\n\t{\n\t\t[field:SerializeField] public UnityEngine.CharacterController Controller { get;private set; }\n\t\t[field:SerializeField] public Vector3 CurrentMoveDirection { get; private set; }\n\t\tpublic float VerticalVelocity => verticalVelocity;\n\t\t\n\t\tprivate Vector3 slideVelocity;\n\t\tprivate float verticalVelocity;\n\t\tprivate static readonly int XHash = Animator.StringToHash(\"X\");\n\t\tprivate static readonly int YHash = Animator.StringToHash(\"Y\");\n\t\t\n\t\tpublic void Initialize(CharacterSetup setup)\n\t\t{\n\t\t}\n\t\tpublic void HandleRotation(float rotationSpeed,Camera cam)\n\t\t{\n\t\t\tvar camForward = cam.transform.forward;\n\t\t\tcamForward.y = 0f;\n\t\t\tif (camForward.sqrMagnitude < 0.001f) return;\n\n\t\t\tvar targetRotation = Quaternion.LookRotation(camForward.normalized);\n\t\t\tController.transform.rotation = Quaternion.Slerp(Controller.transform.rotation, targetRotation,\n\t\t\t\trotationSpeed * Time.deltaTime);\n\t\t}\n\t\tpublic void HandleMovement(CharacterSetup characterSetup, Camera cam)\n\t\t{\n\t\t\tvar data = characterSetup.CharacterData;\n\t\t\tvar direction = characterSetup.ReadInput.Direction;\n\n\t\t\tvar camForward = cam.transform.forward; camForward.y = 0f; camForward.Normalize();\n\t\t\tvar camRight   = cam.transform.right;   camRight.y   = 0f; camRight.Normalize();\n\t\t\tvar moveDir = (camForward * direction.y + camRight * direction.x).normalized;\n\t\t\tvar hasInput = direction.magnitude > 0.1f;\n\n\t\t\tif (characterSetup.Grounded)\n\t\t\t{\n\t\t\t\tvar target = moveDir * characterSetup.MoveState.MoveSpeed;\n\t\t\t\tvar rate = hasInput ? data.playerAcceleration : data.playerDeceleration;\n\t\t\t\tCurrentMoveDirection = Vector3.MoveTowards(CurrentMoveDirection, target, rate * Time.deltaTime);\n\t\t\t\tcharacterSetup.airSpeedCap = CurrentMoveDirection.magnitude;\n\t\t\t}\n\t\t\telse if (characterSetup.Sliding)\n\t\t\t{\n\t\t\t\tvar target = hasInput ? moveDir * data.playerVelocity : Vector3.zero;\n\t\t\t\tCurrentMoveDirection = Vector3.MoveTowards(CurrentMoveDirection, target,\n\t\t\t\t\tdata.slideControl * Time.deltaTime);\n\t\t\t\tcharacterSetup.airSpeedCap = CurrentMoveDirection.magnitude;\n\t\t\t}\n\t\t\telse if (hasInput)\n\t\t\t{\n\t\t\t\tvar cap = Mathf.Max(characterSetup.airSpeedCap, data.playerVelocity);\n\t\t\t\tCurrentMoveDirection = Vector3.MoveTowards(CurrentMoveDirection, moveDir * cap,\n\t\t\t\t\t8 * Time.deltaTime);\n\t\t\t}\n\t\t\tApplySlide(characterSetup);\n\t\t\tController.Move((CurrentMoveDirection + slideVelocity + Vector3.up * verticalVelocity) * Time.deltaTime);\n\t\t}\n\t\tpublic void ApplyGravity(CharacterSetup characterSetup)\n\t\t{\n\t\t\tvar data = characterSetup.CharacterData;\n\t\t\tif (characterSetup.Grounded && verticalVelocity < 0f)\n\t\t\t{\n\t\t\t\tverticalVelocity = -2f;\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tvar g = data.Gravity * (verticalVelocity < 0f ? data.fallMultiplier : 1f);\n\t\t\tverticalVelocity = Mathf.Max(verticalVelocity + g * Time.deltaTime, -data.maxFallSpeed);\n\t\t}\n\t\tpublic void Jump(CharacterSetup characterSetup)\n\t\t{\n\t\t\tvar input = characterSetup.ReadInput;\n\t\t\tif (!input.isJumping) return;\n\n\t\t\tinput.isJumping = false;\n\n\t\t\tVaulting.TryVault(characterSetup, CurrentMoveDirection.magnitude);\n\t\t\tif (characterSetup.MoveState is VaultState) return;\n\n\t\t\tif (characterSetup.CanJump)\n\t\t\t\tverticalVelocity = characterSetup.CharacterData.JumpForce;\n\t\t}\n\t\tpublic void Climb(CharacterSetup characterSetup, float speed,RaycastHit hit)\n\t\t{\n\t\t\tvar data = characterSetup.CharacterData;\n\t\t\tvar input = characterSetup.ReadInput.Direction;\n\t\t\tvar t = Controller.transform;\n\n\t\t\tvar origin = t.position + Vector3.up * (Controller.height * 0.6f);\n\t\t\tif (!RaycastChecker.Check(origin, t.forward, 0.5f, GameLayers.Climb, out hit, new Color(1, 0, 0)))\n\t\t\t\treturn;\n\n\t\t\tvar wallNormal = hit.normal;\n\n\t\t\tvar flat = new Vector3(-wallNormal.x, 0f, -wallNormal.z);\n\t\t\tif (flat.sqrMagnitude > 0.001f)\n\t\t\t\tt.rotation = Quaternion.Slerp(t.rotation, Quaternion.LookRotation(flat.normalized),\n\t\t\t\t\tdata.rotationSpeed * Time.deltaTime);\n\n\t\t\tvar right = Vector3.Cross(Vector3.up, -wallNormal);\n\t\t\tvar move = (right * input.x + Vector3.up * input.y) * speed;\n\n\t\t\tvar wantedDistance = Controller.radius + 0.05f;\n\t\t\tmove += -wallNormal * ((hit.distance - wantedDistance) * 10f);\n\n\t\t\tController.Move(move * Time.deltaTime);\n\n\t\t\tcharacterSetup.Animator.SetFloat(XHash, input.x, 0.1f, Time.deltaTime);\n\t\t\tcharacterSetup.Animator.SetFloat(YHash, input.y, 0.1f, Time.deltaTime);\n\t\t}\n\t\tprivate void ApplySlide(CharacterSetup characterSetup)\n\t\t{\n\t\t\tCharacterData data = characterSetup.CharacterData;\n\t\t\tGroundInfo ground = characterSetup.GroundInfo;\n\n\t\t\tif (ground.Touching && !ground.Walkable)\n\t\t\t{\n\t\t\t\tvar slideDir = Vector3.ProjectOnPlane(Vector3.down, ground.Normal).normalized;\n\t\t\t\tslideVelocity = Vector3.MoveTowards(slideVelocity, slideDir * data.slideSpeed,\n\t\t\t\t\tdata.slideAcceleration * Time.deltaTime);\n\n\t\t\t\tvar uphill = new Vector3(ground.Normal.x, 0f, ground.Normal.z).normalized;\n\t\t\t\tvar into = Vector3.Dot(CurrentMoveDirection, -uphill);\n\t\t\t\tif (into > 0f) CurrentMoveDirection += uphill * into;\n\n\t\t\t\tverticalVelocity = Mathf.Max(verticalVelocity, -2f);\n\t\t\t}\n\t\t\telse\n\t\t\t{\n\t\t\t\tslideVelocity = Vector3.MoveTowards(slideVelocity, Vector3.zero,\n\t\t\t\t\tdata.slideAcceleration * Time.deltaTime);\n\t\t\t}\n\t\t}\n\t\tpublic void ResetMotion()\n\t\t{\n\t\t\tCurrentMoveDirection = Vector3.zero;\n\t\t\tverticalVelocity = 0f;\n\t\t}\n\t\t\n\t}\n}"},{"name":"Vaulting.cs","code":"using System.Linq;\nusing CharacterController.Script.PlayerControllers.Utilities;\nusing CharacterController.Utilities;\nusing Script.PlayerControllers;\nusing UnityEngine;\n\nnamespace CharacterController.Script.PlayerControllers\n{\n\tpublic static class Vaulting\n\t{\n\t\tpublic static void TryVault(CharacterSetup characterSetup, float currentSpeed)\n\t\t{\n\t\t\tvar data = characterSetup.CharacterData;\n\n\t\t\tvar maxScanDistance = data.vaultAnimations.Max(a => a.forwardCheckDistance);\n\t\t\tvar maxScanHeight = data.vaultAnimations.Max(a => a.maxObstacleHeight);\n\n\t\t\tif (!TryDetectObstacle(characterSetup, maxScanDistance, maxScanHeight, out var topPoint,\n\t\t\t\t    out var obstacleHeight))\n\t\t\t\treturn;\n\n\t\t\tvar selected = SelectAnimData(currentSpeed, obstacleHeight, data);\n\t\t\tif (selected == null)\n\t\t\t\treturn;\n\n\t\t\tcharacterSetup.GoTo(new VaultState(topPoint, selected));\n\t\t}\n\n\t\tprivate static bool TryDetectObstacle(CharacterSetup characterSetup, float forwardDistance, float maxScanHeight,\n\t\t\tout Vector3 topPoint, out float obstacleHeight)\n\t\t{\n\t\t\ttopPoint = Vector3.zero;\n\t\t\tobstacleHeight = 0f;\n\n\t\t\tvar pos = characterSetup.transform;\n\t\t\tvar data = characterSetup.CharacterData;\n\t\t\tvar origin = pos.position +  Vector3.up * 0.6f * data.vaultOrigin;\n\n\t\t\tif (!RaycastChecker.Check(origin, pos.forward, forwardDistance, GameLayers.Vaultable, out var forwardHit,\n\t\t\t\t    new Color(0, 1, 0)))\n\t\t\t\treturn false;\n\n\t\t\tvar topCheckOrigin = forwardHit.point + pos.forward * 0.1f + Vector3.up * maxScanHeight;\n\t\t\tif (!RaycastChecker.Check(topCheckOrigin, Vector3.down, maxScanHeight, GameLayers.Vaultable, out var topHit,\n\t\t\t\t    Color.yellow))\n\t\t\t\treturn false;\n\n\t\t\ttopPoint = topHit.point;\n\t\t\tobstacleHeight = topHit.point.y - pos.position.y;\n\t\t\treturn true;\n\t\t}\n\n\t\tprivate static VaultAnimData SelectAnimData(float speed, float obstacleHeight, CharacterData data)\n\t\t{\n\t\t\tforeach (var entry in data.vaultAnimations)\n\t\t\t{\n\t\t\t\tvar heightMatches = obstacleHeight >= entry.minObstacleHeight &&\n\t\t\t\t                    obstacleHeight <= entry.maxObstacleHeight;\n\t\t\t\tvar speedMatches = speed >= entry.speedMin;\n\n\t\t\t\tif (heightMatches && speedMatches)\n\t\t\t\t\treturn entry;\n\t\t\t}\n\n\t\t\treturn null;\n\t\t}\n\t}\n}"},{"name":"NormalWalk.cs","code":"using CharacterController.SaverioScript.PlayerControllers.CharacterController.MoveState;\nusing CharacterController.Script;\nusing CharacterController.Script.PlayerControllers;\n\nnamespace CharacterController\n{\n\tpublic class NormalWalk : IMoveState\n\t{\n\t\tpublic float MoveSpeed { get; set; }\n\n\t\tpublic void EnterState(CharacterSetup characterSetup)\n\t\t{\n\t\t\tMoveSpeed = characterSetup.CharacterData.playerVelocity;\n\t\t}\n\n\t\tpublic void UpdateState(CharacterSetup characterSetup)\n\t\t{\n\t\t\t\tvar input = characterSetup.ReadInput;\n\n\t\t\t\tif (input.Interact && characterSetup.Grounded && !characterSetup.Sliding && characterSetup.Grabber.CanGrab()) \n\t\t\t\t{ \n\t\t\t\t\tcharacterSetup.GoTo(new GrabState()); \n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tif (characterSetup.Sliding)                     \n\t\t\t\t{ \n\t\t\t\t\tcharacterSetup.GoTo(new SlideDownState()); \n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tif (input.isJumping && characterSetup.Climb)\n\t\t\t\t{ \n\t\t\t\t\tcharacterSetup.GoTo(new ClimbState());     \n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tif (input.IsFighting)\n\t\t\t\t{\n\t\t\t\t\tcharacterSetup.GoTo(new FightState());\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tif (input.IsRunning)\n\t\t\t\t{\n\t\t\t\t\tcharacterSetup.GoTo(new RunState());\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tif (input.IsCrunching)\n\t\t\t\t{ \n\t\t\t\t\tcharacterSetup.GoTo(new CrounchState());\n\t\t\t\t\treturn; \n\t\t\t\t}\n\t\t}\n\t\tpublic void ExitState(CharacterSetup characterSetup)\n\t\t{\n\t\t}\n\t}\n}"}],"videos":[["CHARACTER CONTROLLER — DÉMO","assets/videos/character-controller.mp4"]]},"ai":{"title":"IA D’INFILTRATION","eyebrow":"SYS / 003 — PERCEPTION & STATES","fr":"L’IA des PNJ repose sur un cerveau central et des aptitudes spécialisées. BrainPnj configure le NavMeshAgent, l’Animator et le ragdoll, initialise les PnjAptitude, puis fait évoluer un objet d’état IPnjStates à chaque frame. Les événements de VisionCone et AuditionCast peuvent interrompre la routine courante pour déclencher une réaction. PatrolState suit une liste de points avec des temps d’arrêt ; ChaseState poursuit la dernière position visible et peut demander une action alternative si la cible est hors de portée directe ; SearchState génère une série de points autour de la dernière position connue et revient ensuite à la patrouille. DetectionSense factorise la cadence de scan, les masques de cibles et d’obstacles, l’origine du capteur et le filtrage. AuditionCast spécialise cette base avec un rayon d’alerte rapproché. Les six scripts affichés sont les extraits transmis, pas l’intégralité des aptitudes et états référencés.","en":"The NPC AI is built around a central brain and specialized abilities. BrainPnj configures the NavMeshAgent, Animator and ragdoll, initializes PnjAptitude components, then updates an IPnjStates state every frame. VisionCone and AuditionCast events can interrupt the current routine and trigger a reaction. PatrolState follows a list of points with pauses; ChaseState follows the last visible position and can request an alternative action when the target is not directly reachable; SearchState generates points around the last known position before returning to patrol. DetectionSense centralizes scan cadence, target and obstacle masks, sensor origin and filtering. AuditionCast specializes this base with a close danger radius. The six scripts shown are the supplied excerpts, not every referenced ability and state.","architecture":"BrainPnj\n ├─ PnjAptitude / GetAptitude<T>()\n ├─ VisionCone / AuditionCast\n ├─ DetectionSense\n ├─ IPnjStates\n └─ Patrol / Chase / Search / KO","flow":"Patrouille → perception visuelle ou sonore → réaction dédiée → poursuite → recherche de la dernière position connue → reprise de la patrouille.","points":["BrainPnj : initialise les composants, centralise les événements de perception et orchestre les transitions d’état.","DetectionSense : classe abstraite qui mutualise les scans, les filtres physiques et la mémorisation de position.","AuditionCast : déclenche une alerte lorsqu’une cible sonore est trouvée dans le rayon de danger.","PatrolState : suit la routine du PNJ et gère les pauses / rotations aux points de passage.","ChaseState : poursuit la cible visible, mémorise sa dernière position et bascule vers la recherche si elle est perdue.","SearchState : inspecte des points autour de la dernière position connue avant de reprendre la patrouille."],"scripts":[{"name":"BrainPnj.cs","code":"using System;\nusing System.Collections.Generic;\nusing PnjDetection;\nusing PnjStates;\nusing RagdollSysteme;\nusing Routine;\nusing UnityEngine;\nusing UnityEngine.AI;\n\npublic class BrainPnj : RagDoll\n{\n    [SerializeField] private List<PnjAptitude> aptitudes = new List<PnjAptitude>();\n    [field:SerializeField] public NavMeshAgent Agent {get; private set;}\n    [field:SerializeField] public List<PointTime> FirstRoutine {get; private set;} = new List<PointTime>();\n    [field:SerializeField] public int currentStep = 0;\n    [field:SerializeField] public Animator Animator {get; private set;}\n    [field:SerializeField] public Transform Model {get; private set;}\n\n    public IPnjStates PNJStates { get; private set; }\n    public event Action<IPnjStates> OnStatesChanged;\n    \n    private Rigidbody[] ragdollRigidbodies;\n    private Collider mainCollider;\n\n    private void Awake()\n    {\n       Animator = GetComponentInChildren<Animator>();\n       Agent = GetComponent<NavMeshAgent>();\n\n       ragdollRigidbodies = GetComponentsInChildren<Rigidbody>();\n       mainCollider = GetComponent<Collider>();\n\n       SetRagdollPhysics(false);\n\n       PnjAptitude[] found = GetComponents<PnjAptitude>();\n       aptitudes.AddRange(found);\n\n       foreach (PnjAptitude aptitude in aptitudes)\n       {\n          aptitude.Init(this);\n       }\n    }\n\n    private void OnEnable()\n    {\n       VisionCone vision = GetAptitude<VisionCone>();\n       if (vision != null)\n          vision.OnTargetSeen += HandleTargetSeen;\n\n       AuditionCast audition = GetAptitude<AuditionCast>();\n       if (audition != null)\n          audition.OnHearAlerte += HandleTargetSound;\n\n       OnRagdoll += KoMode;\n       OnWakeUp += DisableRagdollPhysics;\n    }\n\n    private void OnDisable()\n    {\n       VisionCone vision = GetAptitude<VisionCone>();\n       if (vision != null)\n          vision.OnTargetSeen -= HandleTargetSeen;\n\n       AuditionCast audition = GetAptitude<AuditionCast>();\n       if (audition != null)\n          audition.OnHearAlerte -= HandleTargetSound;\n       OnRagdoll -= KoMode;\n       OnWakeUp -= DisableRagdollPhysics;\n    }\n\n    private void DisableRagdollPhysics()\n    {\n        Transform hips = Animator.GetBoneTransform(HumanBodyBones.Hips);\n        Vector3 hipsPos = hips.position;\n        Quaternion hipsRot = hips.rotation;\n\n        SetRagdollPhysics(false);\n\n        if (NavMesh.SamplePosition(hipsPos, out NavMeshHit hit, 5f, NavMesh.AllAreas))\n        {\n            Agent.enabled = false;\n            Quaternion yaw = Quaternion.Euler(0f, hipsRot.eulerAngles.y, 0f);\n            transform.SetPositionAndRotation(hit.position, yaw);\n            hips.SetPositionAndRotation(hipsPos, hipsRot);\n            Agent.enabled = true;\n            Agent.Warp(hit.position);\n        }\n        else\n        {\n            Debug.LogWarning($\"{name}: aucun NavMesh à moins de 5m du ragdoll.\");\n        }\n    }\n\n    private void SetRagdollPhysics(bool enableRagdoll)\n    {\n       if (ragdollRigidbodies != null)\n       {\n          foreach (Rigidbody rb in ragdollRigidbodies)\n             rb.isKinematic = !enableRagdoll;\n       }\n       if (mainCollider != null)\n          mainCollider.enabled = !enableRagdoll;\n    }\n\n    private void HandleTargetSeen(Vector3 pos, IDetected target)\n    {\n       if (PNJStates is SuspiciousState || PNJStates is ChaseState || PNJStates is SurpriseState || PNJStates is KoState)\n          return;\n       PnjGoTo(new SurpriseState(target));\n    }\n\n    private void HandleTargetSound(ISondDetected target, GameObject targetPosition)\n    {\n       if (PNJStates is SurpriseState || PNJStates is ChaseState || PNJStates is IntrigueState|| PNJStates is KoState)\n          return;\n       PnjGoTo(new IntrigueState(target, targetPosition));\n    }\n\n    private void Start()\n    {\n       PnjGoTo(new PatrolState(this));\n    }\n\n    private void Update()\n    {\n       PNJStates.UpdateState(this);\n    }\n\n    public T GetAptitude<T>() where T : PnjAptitude\n    {\n       foreach (PnjAptitude aptitude in aptitudes)\n       {\n          if (aptitude is T match)\n             return match;\n       }\n       return null;\n    }\n\n    public void PnjGoTo(IPnjStates state)\n    {\n       PNJStates?.ExitState(this);\n       PNJStates = state;\n       PNJStates?.EnterState(this);\n       OnStatesChanged?.Invoke(PNJStates);\n    }\n\n    public void KoMode()\n    {\n       Agent.enabled = false;\n       SetRagdollPhysics(true);\n       PnjGoTo(new KoState());\n    }\n}"},{"name":"PatrolState.cs","code":"using Goblfin.PnjSystem.Utilities;\nusing UnityEngine;\n\nnamespace Goblfin.PnjSystem\n{\n\tpublic class PatrolState : IPnjStates\n\t{\n\t\tpublic StatePriority Priority => StatePriority.Patrol;\n\t\tpublic float AgentSpeed => GameMetrix.GuardPatrolSpeed;\n\t\tprivate readonly BrainPnj guard;\n\t\tprivate float waitTimer;\n\t\tprivate bool isWaiting;\n\t\t\n\t\tpublic PatrolState(BrainPnj brainPnj)\n\t\t{\n\t\t\tthis.guard = brainPnj;\n\t\t}\n\n\t\tpublic void EnterState(BrainPnj brainPnj)\n\t\t{\n\t\t\tDebug.Log(\"PatrolState\");\n\t\t\tbrainPnj.Agent.speed = AgentSpeed;\n\t\t\tGoToCurrentPoint();\n\t\t}\n\n\t\tpublic void UpdateState(BrainPnj brainPnj)\n\t\t{\n\t\t\tif (isWaiting)\n\t\t\t{\n\t\t\t\tbrainPnj.Agent.speed = 0;\n\t\t\t\tguard.transform.rotation = Quaternion.Slerp(\n\t\t\t\t\tguard.transform.rotation,\n\t\t\t\t\tguard.RoutinePattern[guard.currentStep].targetRotation,\n\t\t\t\t\tTime.deltaTime * 5f\n\t\t\t\t);\n\t\t\t\twaitTimer -= Time.deltaTime;\n\n\t\t\t\tif (waitTimer <= 0f)\n\t\t\t\t{\n\t\t\t\t\tbrainPnj.Agent.speed = GameMetrix.GuardPatrolSpeed;\n\t\t\t\t\tisWaiting = false;\n\t\t\t\t\tguard.currentStep = (guard.currentStep + 1) % guard.RoutinePattern.Count;\n\t\t\t\t\tGoToCurrentPoint();\n\t\t\t\t}\n\t\t\t}\n\t\t\telse if (!guard.Agent.pathPending && guard.Agent.remainingDistance < 0.02f)\n\t\t\t{\n\t\t\t\tisWaiting = true;\n\t\t\t\twaitTimer = guard.RoutinePattern[guard.currentStep].GetComponent<Routine.PointTime>().MinTime;\n\t\t\t}\n\t\t}\n\n\t\tpublic void ExitState(BrainPnj brainPnj)\n\t\t{\n\t\t\tisWaiting = false;\n\t\t}\n\t\t\n\t\tvoid GoToCurrentPoint()\n\t\t{\n\t\t\tguard.Agent.destination = guard.RoutinePattern[guard.currentStep].transform.position;\n\t\t}\n\t}\n}"},{"name":"ChaseState.cs","code":"using Goblfin.PnjSystem.Utilities;\nusing UnityEngine;\n\nnamespace Goblfin.PnjSystem\n{\n\tpublic class ChaseState : IPnjStates\n\t{\n\t\tprivate IDetected target;\n\t\tprivate Vector3 lastKnownPosition;\n\t\tprivate VisionCone vision;\n\t\tfloat nextReachCheck;\n\t\tprivate ThrowThingsManager thrower;\n\n\t\tpublic ChaseState(IDetected target)\n\t\t{\n\t\t\tthis.target = target;\n\t\t\tlastKnownPosition = target.transform.position;\n\t\t}\n\t\tpublic StatePriority Priority => StatePriority.Chase;\n\t\tpublic float AgentSpeed => GameMetrix.GuardChaseSpeed;\n\n\t\tpublic void EnterState(BrainPnj brainPnj)\n\t\t{\n\t\t\tDebug.Log(\"Chase State\");\n\t\t\tbrainPnj.Agent.speed = AgentSpeed;\n\t\t\tvision = brainPnj.GetAptitude<VisionCone>();\n\t\t\tthrower = brainPnj.GetAptitude<ThrowThingsManager>();\n\t\t\tnextReachCheck = Time.time + 0.5f;\n\t\t}\n\n\t\tpublic void UpdateState(BrainPnj brainPnj)\n\t\t{\n\t\t\tvar canSee = vision.CanSee(target);\n\t\t\tif (canSee)\n\t\t\t{\n\t\t\t\tlastKnownPosition = target.transform.position;\n\n\t\t\t\tif (Time.time >= nextReachCheck)\n\t\t\t\t{\n\t\t\t\t\tnextReachCheck = Time.time + 0.5f;\n\n\t\t\t\t\tif (thrower != null && thrower.RocksLeft > 0\n\t\t\t\t\t                    && thrower.InRange(lastKnownPosition)\n\t\t\t\t\t                    && !thrower.CanReach(lastKnownPosition))\n\t\t\t\t\t{\n\t\t\t\t\t\tbrainPnj.PnjGoTo(new ThrowState(target));\n\t\t\t\t\t\treturn;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tbrainPnj.Agent.SetDestination(lastKnownPosition);\n\t\t\t}\n\t\t\tif (!canSee && !brainPnj.Agent.pathPending && brainPnj.Agent.remainingDistance < 0.2f)\n\t\t\t\tbrainPnj.PnjGoTo(new SearchState(brainPnj,lastKnownPosition));\n\t\t}\n\n\t\tpublic void ExitState(BrainPnj brainPnj)\n\t\t{\n\t\t}\n\t}\n}"},{"name":"SearchState.cs","code":"using System.Collections.Generic;\nusing Goblfin.PnjSystem.Utilities;\nusing PrimeTween;\nusing UnityEngine;\n\nnamespace Goblfin.PnjSystem\n{\n    public class SearchState : IPnjStates\n    {\n\t    public StatePriority Priority => StatePriority.Searching;\n       public float AgentSpeed => GameMetrix.GuardPatrolSpeed;\n       private float timer;\n       private BrainPnj guard;\n       private int currentSearchIndex;\n       private Vector3 lastTargetPos;\n       private List<Vector3> searchPoints = new List<Vector3>();\n       private bool isWaiting;\n\n       private int searchPointCount = GameMetrix.SearchPointCount;\n       public SearchState(BrainPnj guard, Vector3 lastTargetPos)\n       {\n          this.guard = guard;\n          this.lastTargetPos = lastTargetPos;\n       }\n\n       public void EnterState(BrainPnj brainPnj)\n       { \n          timer = 0f;\n          currentSearchIndex = 0;\n          isWaiting = false;\n          \n          guard.Agent.speed = AgentSpeed;\n          searchPointCount += (int)brainPnj.Patience.CurrentPatienceType;\n          searchPoints = GameMetrix.SearchPointsGenerated(lastTargetPos, GameMetrix.SearchRadius, searchPointCount);\n\n          if (searchPoints.Count > 0)\n             brainPnj.Agent.SetDestination(searchPoints[0]);\n       }\n\n       public void UpdateState(BrainPnj brainPnj)\n       {\n          if (searchPoints.Count == 0)\n          {\n             brainPnj.PnjGoTo(new PatrolState(guard));\n             return;\n          }\n\n          if (isWaiting)\n          {\n             timer -= Time.deltaTime;\n             if (timer <= 0f)\n                GoToNextPoint(brainPnj);\n          }\n          else if (!brainPnj.Agent.pathPending && brainPnj.Agent.remainingDistance < 0.5f)\n          {\n             isWaiting = true;\n             timer = GameMetrix.SearchWaitPerPoint;\n          }\n       }\n\n       public void ExitState(BrainPnj brainPnj)\n       {\n          brainPnj.Patience.AddOrRemovePatience(-10);\n          guard.Agent.speed = GameMetrix.GuardPatrolSpeed;\n       }\n       \n       private void GoToNextPoint(BrainPnj brainPnj)\n       {\n          currentSearchIndex++;\n          if (currentSearchIndex >= searchPoints.Count)\n          {\n             brainPnj.PnjGoTo(new PatrolState(guard));\n             return;\n          }\n          isWaiting = false;\n          brainPnj.Agent.SetDestination(searchPoints[currentSearchIndex]);\n       }\n    }\n}"},{"name":"DetectionSense.cs","code":"using System.Collections.Generic;\nusing UnityEngine;\n\nnamespace Goblfin.PnjSystem\n{\n    public abstract class DetectionSense : PnjAptitude\n    {\n        [Header(\"Filtrage commun\")]\n        [SerializeField] protected LayerMask targetMask;\n        [SerializeField] protected LayerMask obstacleMask;\n\n        [Header(\"Décalage du capteur\")]\n        [Tooltip(\"Décalage local du point d'origine du sens (ex: hauteur des yeux).\")]\n        [SerializeField] protected Vector3 sensorOffset;\n\n        [Header(\"Cadence de scan\")]\n        [SerializeField] protected float scanInterval = 0.05f;\n\n        [Header(\"Mémoire\")]\n        [SerializeField] protected List<Transform> detectedTargets = new List<Transform>();\n        [field: SerializeField] public Vector3 LastPos { get; protected set; }\n\n        public Vector3 SensorOrigin => transform.position + transform.TransformDirection(sensorOffset);\n\n        protected virtual void OnEnable()\n        {\n            StartCoroutine(ScanRoutine());\n        }\n\n        private System.Collections.IEnumerator ScanRoutine()\n        {\n            yield return new WaitForSeconds(Random.Range(0f, scanInterval));\n            while (true)\n            {\n                Scan();\n                yield return new WaitForSeconds(scanInterval);\n            }\n        }\n        protected abstract void Scan();\n        \n        protected Transform FindTargetInRadius(float radius)\n        {\n            Vector3 origin = SensorOrigin;\n            Collider[] hits = Physics.OverlapSphere(origin, radius, targetMask);\n            foreach (Collider hit in hits)\n            {\n                Transform target = hit.transform;\n                Vector3 toTarget = target.position - origin;\n                float dist = toTarget.magnitude;\n                if (dist < 0.0001f) continue;\n                Vector3 dir = toTarget / dist;\n                if (!PassesFilter(dir, dist)) continue;\n                if (Physics.Raycast(origin, dir, dist, obstacleMask)) continue;\n                return target;\n            }\n            return null;\n        }\n        protected virtual bool PassesFilter(Vector3 dirToTarget, float distToTarget) => true;\n        protected void Remember(Transform target)\n        {\n            detectedTargets.Add(target);\n            LastPos = target.position;\n        }\n        protected virtual void OnDrawGizmos()\n        {\n            Gizmos.color = Color.blue;\n            foreach (Transform target in detectedTargets)\n                if (target != null) Gizmos.DrawLine(SensorOrigin, target.position);\n        }\n    }\n}"},{"name":"AuditionCast.cs","code":"using System;\nusing UnityEngine;\n\nnamespace Goblfin.PnjSystem\n{\n    public class AuditionCast : DetectionSense\n    {\n        [Header(\"Réglages de la portée de l'audition\")]\n        [Tooltip(\"Rayon proche : une cible ici déclenche une alerte immédiate.\")]\n        [Range(1, 60)]\n        [field: SerializeField] public float DangerHearingRadius { get; private set; } = 5f;\n\n        [Tooltip(\"Rayon large : une cible ici est simplement entendue.\")]\n        [Range(1, 60)]\n        [field: SerializeField] public float HearingRadius { get; private set; } = 10f;\n\n        public event Action<ISondDetected, Transform > OnHearAlerte;\n        \n        protected override void Scan()\n        {\n            detectedTargets.Clear();\n            Transform dangerTarget = FindTargetInRadius(DangerHearingRadius);\n            if (dangerTarget == null) return;\n            ISondDetected target = dangerTarget.GetComponentInParent<ISondDetected>();\n            Remember(dangerTarget);\n            OnHearAlerte?.Invoke(target, this.gameObject.transform);\n        }\n\n        protected override void OnDrawGizmos()\n        {\n            Vector3 origin = SensorOrigin;\n            Gizmos.color = Color.red;\n            Gizmos.DrawWireSphere(origin, DangerHearingRadius);\n            base.OnDrawGizmos();\n        }\n    }\n}"}],"videos":[["CHASE & SEARCH","assets/videos/ai-chase-search.mp4"],["PORTE BLOQUÉE","assets/videos/ai-door-block.mp4"],["INVESTIGATION DU BRUIT","assets/videos/ai-noise-investigation.mp4"],["EMERGENCY STATE","assets/videos/ai-emergency-state.mp4"],["PATROUILLE","assets/videos/ai-patrol.mp4"],["KO STATE","assets/videos/ai-ko-state.mp4"]]}};
function renderSystemDetails(info){
 const codeRoot=$('#dialogCode');
 codeRoot.innerHTML='';
 const intro=document.createElement('section'); intro.className='dialog-section';
 const overview=document.createElement('h3'); overview.textContent=language==='fr'?'INTENTION & FONCTIONNEMENT':'PURPOSE & BEHAVIOUR';
 const description=document.createElement('p'); description.textContent=info[language]; intro.append(overview,description);
 const architectureTitle=document.createElement('h3'); architectureTitle.textContent=language==='fr'?'ARCHITECTURE':'ARCHITECTURE';
 const architecture=document.createElement('pre'); architecture.className='architecture-tree'; architecture.textContent=info.architecture;
 const flowTitle=document.createElement('h3'); flowTitle.textContent=language==='fr'?'FLUX GLOBAL':'HIGH-LEVEL FLOW';
 const flow=document.createElement('p'); flow.className='dialog-flow'; flow.textContent=info.flow;
 const componentsTitle=document.createElement('h3'); componentsTitle.textContent=language==='fr'?'RESPONSABILITÉS DES COMPOSANTS':'COMPONENT RESPONSIBILITIES';
 const list=document.createElement('ul'); list.className='dialog-points'; info.points.forEach(point=>{const li=document.createElement('li');li.textContent=point;list.append(li)});
 const scriptsTitle=document.createElement('h3'); scriptsTitle.className='scripts-heading'; scriptsTitle.textContent=(language==='fr'?'SCRIPTS FOURNIS':'SUPPLIED SCRIPTS')+' · '+info.scripts.length;
 const note=document.createElement('p');note.className='code-disclaimer';note.textContent=language==='fr'?'Code transmis dans la conversation. Les dépendances non fournies ne sont pas reconstituées.':'Code supplied in the conversation. Missing dependencies are not recreated.';
 codeRoot.append(intro,architectureTitle,architecture,flowTitle,flow,componentsTitle,list,scriptsTitle,note);
 info.scripts.forEach((script,index)=>{
   const details=document.createElement('details');details.className='script-accordion';if(index===0)details.open=true;
   const summary=document.createElement('summary');summary.innerHTML='<span>'+script.name+'</span><span class="script-size">C# · '+(script.code.split('\n').length)+' lignes</span>';
   const pre=document.createElement('pre');pre.className='script-source';const code=document.createElement('code');code.textContent=script.code;pre.append(code);details.append(summary,pre);codeRoot.append(details);
 });
}
$$('.details-button').forEach(btn=>btn.addEventListener('click',()=>{
 const info=systemInfo[btn.dataset.system]; activeSystem=info;
 $('#dialogEyebrow').textContent=info.eyebrow; $('#dialogTitle').textContent=info.title;
 renderSystemDetails(info);
 const videos=$('#dialogVideos'); videos.innerHTML=''; info.videos.forEach(([label,src])=>{const figure=document.createElement('figure');figure.className='dialog-video';const video=document.createElement('video');video.controls=true;video.preload='metadata';video.playsInline=true;video.src=src;const caption=document.createElement('figcaption');caption.textContent=label;figure.append(video,caption);videos.append(figure);});
 dialog.showModal();
}));
$('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
$('#year').textContent=new Date().getFullYear();
// Interactive pixel-dot ember field: pointer proximity warms nearby dots.
const canvas=$('#embers'),ctx=canvas.getContext('2d');let w,h,dots=[],pointer={x:-1000,y:-1000};
function resize(){w=canvas.width=innerWidth;h=canvas.height=innerHeight;dots=[];const step=19;for(let y=8;y<h;y+=step)for(let x=8;x<w;x+=step)dots.push({x,y,p:Math.random()*Math.PI*2,r:1.05+Math.random()*.55});}function draw(t=0){ctx.clearRect(0,0,w,h);for(const d of dots){const dx=d.x-pointer.x,dy=d.y-pointer.y,dist=Math.hypot(dx,dy),heat=Math.max(0,1-dist/175),wave=(Math.sin(t*.0012+d.p)+1)*.5;const alpha=.07+wave*.12+heat*.62;ctx.beginPath();ctx.arc(d.x,d.y,d.r+heat*1.5,0,Math.PI*2);ctx.fillStyle=heat>.55?`rgba(255,${Math.floor(85+wave*90)},${Math.floor(15+wave*20)},${alpha})`:`rgba(210,${Math.floor(125+wave*55)},${Math.floor(85+wave*35)},${alpha})`;ctx.fill();}requestAnimationFrame(draw)}addEventListener('resize',resize);addEventListener('pointermove',e=>{pointer.x=e.clientX;pointer.y=e.clientY});addEventListener('pointerleave',()=>{pointer.x=-1000;pointer.y=-1000});resize();requestAnimationFrame(draw);
